class User {
  constructor(name) {
    this.name = name;
  }

  describe() {
    return `User: ${this.name}`;
  }
}

class Admin extends User {
  constructor(name, level) {
    super(name);
    this.level = level;
  }

  describe() {
    return `${super.describe()} (${this.level})`;
  }
}

const asha = new Admin('Asha', 'senior');
console.log(asha.describe());
console.log(asha instanceof Admin, asha instanceof User);

