class User {
  #age;

  constructor(name, age) {
    this.name = name;
    this.age = age;
  }

  get age() {
    return this.#age;
  }

  set age(value) {
    if (!Number.isInteger(value) || value < 0 || value > 150) {
      throw new RangeError('Invalid age');
    }
    this.#age = value;
  }
}

const kakade = new User('Kakade', 30);
console.log(kakade.age);
try {
  kakade.age = -1;
} catch (error) {
  console.log(error.constructor.name);
}

