questions.answer:
class User {
  constructor(name, role = 'member') {
    this.name = name;
    this.role = role;
  }

  static fromJSON(json) {
    const data = JSON.parse(json);
    return new this(data.name, data.role);
  }
}

console.log(User.fromJSON('{"name":"Kakade"}').role);

